import os
import json
from web3 import Web3
from dotenv import load_dotenv

load_dotenv()

# 1. Celo Sepolia Configuration
RPC_URL = os.getenv("BLOCKCHAIN_RPC_URL", "https://forno.celo-sepolia.celo-testnet.org")
PRIVATE_KEY = os.getenv("WALLET_PRIVATE_KEY")

if not PRIVATE_KEY:
    raise ValueError("WALLET_PRIVATE_KEY is missing in your .env file!")

# Ensure private key has 0x prefix
if not PRIVATE_KEY.startswith("0x"):
    PRIVATE_KEY = "0x" + PRIVATE_KEY

w3 = Web3(Web3.HTTPProvider(RPC_URL))
account = w3.eth.account.from_key(PRIVATE_KEY)

print(f"Connecting to: {RPC_URL}")
print(f"Deployer Address: {account.address}")
print(f"Native Balance: {w3.from_wei(w3.eth.get_balance(account.address), 'ether')} CELO")

