# Paste the "object" hex string from Remix's Bytecode copy button below (starts with 0x6080...)
# If you don't have it, paste it between the quotes:
BYTECODE = ""


def deploy():
    contract = w3.eth.contract(abi=ABI, bytecode=BYTECODE)
    
    # Build transaction
    nonce = w3.eth.get_transaction_count(account.address)
    tx = contract.constructor().build_transaction({
        'from': account.address,
        'nonce': nonce,
        'gasPrice': w3.eth.gas_price,
    })
    
    print("Signing and sending deployment transaction...")
    signed_tx = w3.eth.account.sign_transaction(tx, PRIVATE_KEY)
    tx_hash = w3.eth.send_raw_transaction(signed_tx.raw_transaction)
    print(f"Tx Hash: {tx_hash.hex()}")
    print("Waiting for block confirmation...")
    
    receipt = w3.eth.wait_for_transaction_receipt(tx_hash)
    print("\nSUCCESS! Contract deployed at:")
    print(f"CONTRACT_ADDRESS=\"{receipt.contractAddress}\"")

if __name__ == "__main__":
    deploy()